import { connection } from 'next/server'

import { toggleNotifications } from './actions'
import { CURRENT_USER_ID, getNotificationPreference } from './lib/preferences'

export default async function Home() {
  // The preference is request-time state, so keep this page out of the build-time
  // prerender — otherwise the refresh triggered by the action would just re-serve
  // the statically cached HTML.
  await connection()
  const enabled = await getNotificationPreference(CURRENT_USER_ID)

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? 'Turn off notifications' : 'Turn on notifications'}
        </button>
      </form>
    </main>
  )
}

